@PluginDescriptor(
		name = "HD Minimap",
		description = "Adds a HD Minimap from 2008, as well as the ability to remove icons and scenery from the maps!",
		tags = {"hd", "minimap", "map", "scenery", "icons"}
)

@Slf4j
public class HDMinimapPlugin extends Plugin {

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private HDRenderer hdRenderer;

	@Inject
	private HDMinimapConfig config;

	@Inject
	private MapElementManager mapElementManager;

	private MinimapStyle currentStyle;

	@Setter(AccessLevel.PACKAGE)
	private MinimapPanel panel;

	private NavigationButton button;

	@Inject
	private ClientToolbar clientToolbar;

	private Double lastZoom = null;


	@Provides
	HDMinimapConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(HDMinimapConfig.class);
	}

	@Override
	protected void startUp() {
		clientThread.invoke(this::setupPanel);

		currentStyle = config.minimapStyle();
		setMinimapDrawer();
		reloadGame();
		lastZoom = client.getMinimapZoom();
	}

	private void setupPanel() {
		mapElementManager.start(client);

		panel = injector.getInstance(MinimapPanel.class);
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		button = NavigationButton.builder()
				.tooltip("HD Minimap")
				.icon(icon)
				.priority(3)
				.panel(panel)
				.build();

		if (config.displaySidebar()) {
			clientToolbar.addNavigation(button);
		}
	}

	@Inject
	private PluginManager pluginManager;

	@Override
	public void shutDown() {
		clientToolbar.removeNavigation(button);
		client.setMinimapTileDrawer(null);
		client.getObjectCompositionCache().reset();
		reloadGame();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (event.getGroup().equals(HDMinimapConfig.CONFIG_GROUP)) {
			if (Objects.equals(event.getKey(), "minimapStyle")) {
				currentStyle = config.minimapStyle();
				setMinimapDrawer();
				log.debug("Minimap style changed to: {}", currentStyle);
			}
			if (Objects.equals(event.getKey(), "mapElementView")) {
				panel.rebuild(mapElementManager,config);
			}
			if (Objects.equals(event.getKey(), "minimapSideBar")) {
				if (config.displaySidebar()) {
					clientToolbar.addNavigation(button);
				} else {
					clientToolbar.removeNavigation(button);
				}
				client.getObjectCompositionCache().reset();
				reloadGame();
			}
		}
		if (event.getGroup().equals(MapElementManager.CONFIG_GROUP)) {
			reloadGame();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged) {
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN && config.displaySidebar()) {
			mapElementManager.updateAllIcons();
		}
	}

	public void setMinimapDrawer() {
		if (currentStyle != MinimapStyle.DEFAULT) {
			client.setMinimapTileDrawer(this::drawMapTile);
		} else {
			client.setMinimapTileDrawer(null);
		}
	}

	@Subscribe
	public void onGameTick(GameTick gameTick) {
		if (!config.displaySidebar()) return;
		double zoom = client.getMinimapZoom();
		if (lastZoom != zoom) {
			boolean shouldReload = false;
			for (MapElementCategories entry : MapElementCategories.values()) {
				MapElementSetting setting = mapElementManager.getSetting(entry.getDefaultName());
				Float scale = setting.getScale();
				if (setting.isDisabled() && scale != null) {
					if ((scale <= zoom && scale >= lastZoom) ||
							(scale >= zoom && scale <= lastZoom)) {
						mapElementManager.updateIcon(entry.getDefaultName());
						shouldReload = true;
					}
				}
			}
			if (shouldReload) {
				reloadGame();
			}

			lastZoom = zoom;
		}
	}

	/**
	 * Refreshes the game state if needed when switching to HD117 minimap style
	 */
	private void reloadGame() {
		clientThread.invoke(() -> {
			if (client.getGameState() == GameState.LOGGED_IN) {
				client.setGameState(GameState.LOADING);
				if (client.getWorldMap().getWorldMapRenderer().isLoaded()) {
					client.getWorldMap().initializeWorldMap(client.getWorldMap().getWorldMapData());
				}
			}
		});
	}

	/**
	 * Draws a minimap tile using the currently selected renderer
	 *
	 * @param tile the tile to draw
	 * @param tx   tile x coordinate
	 * @param ty   tile y coordinate
	 * @param px0  pixel x start coordinate
	 * @param py0  pixel y start coordinate
	 * @param px1  pixel x end coordinate
	 * @param py1  pixel y end coordinate
	 */
	public void drawMapTile(Tile tile, int tx, int ty, int px0, int py0, int px1, int py1) {
		hdRenderer.drawMapTile(tile, tx, ty, px0, py0, px1, py1);
	}
}

package io.mark.hdminimap.utils;

import net.runelite.api.IndexedSprite;

import java.awt.image.BufferedImage;

public class ImageUtils {

    public static BufferedImage toBufferedImage(IndexedSprite indexedSprite) {
        int width = indexedSprite.getWidth();
        int height = indexedSprite.getHeight();

        if (width <= 0 || height <= 0) {
            return null;
        }

        BufferedImage bi = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        int[] palette = indexedSprite.getPalette();
        byte[] pixels = indexedSprite.getPixels();

        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                int i = x + y * width;
                int colour = palette[pixels[i] & 0xFF];
                if (colour != 0) {
                    bi.setRGB(x, y, 0xFF000000 | colour);
                }
            }
        }

        return bi;
    }
}

package io.mark.hdminimap.ui;

import io.mark.hdminimap.HDMinimapConfig;
import io.mark.hdminimap.mapelement.MapElementManager;
import io.mark.hdminimap.mapelement.MapElementType;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class MinimapPanel extends PluginPanel {

	@Inject
	private MinimapPanel(MapElementManager mapElementManager, HDMinimapConfig config) {
		super(false);

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel display = new JPanel();
		MaterialTabGroup tabGroup = new MaterialTabGroup(display);

		MaterialTab mapFunctionTab = new MaterialTab("Map Icons", tabGroup, new MapIconViewer(mapElementManager, MapElementType.MAP_FUNCTION, config));
		MaterialTab mapSceneTab = new MaterialTab("Map Scenery", tabGroup, new MapIconViewer(mapElementManager, MapElementType.MAP_SCENERY, config));

		tabGroup.setBorder(new EmptyBorder(5, 0, 0, 0));
		tabGroup.addTab(mapFunctionTab);
		tabGroup.addTab(mapSceneTab);
		tabGroup.select(mapFunctionTab);

		add(tabGroup, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);
	}

	public void rebuild(MapElementManager mapElementManager, HDMinimapConfig config) {
		removeAll();

		JPanel display = new JPanel();
		MaterialTabGroup tabGroup = new MaterialTabGroup(display);

		MaterialTab mapFunctionTab = new MaterialTab(
				"Map Icons",
				tabGroup,
				new MapIconViewer(mapElementManager, MapElementType.MAP_FUNCTION, config)
		);

		MaterialTab mapSceneTab = new MaterialTab(
				"Map Scenery",
				tabGroup,
				new MapIconViewer(mapElementManager, MapElementType.MAP_SCENERY, config)
		);

		tabGroup.setBorder(new EmptyBorder(5, 0, 0, 0));
		tabGroup.addTab(mapFunctionTab);
		tabGroup.addTab(mapSceneTab);
		tabGroup.select(mapFunctionTab);

		add(tabGroup, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);

		revalidate();
		repaint();
	}
}

package io.mark.hdminimap.ui;

import io.mark.hdminimap.HDMinimapConfig;
import io.mark.hdminimap.mapelement.MapElementManager;
import io.mark.hdminimap.mapelement.MapElementType;
import io.mark.hdminimap.mapelement.MapElementCategories;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.ui.components.PluginErrorPanel;

import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;

public class MapIconViewer extends JPanel {
	private final MapElementType mapElementType;
	private final MapElementManager mapElementManager;
	private final HDMinimapConfig config;

	private static final int BUTTON_SIZE = 27;
	private static final boolean SHOW_SORT_DROPDOWN = true;

	private final JPanel buttonPanel;
	private final JPanel buttonsFlowPanel;
	private final JPanel inlineConfigPanel;
	private final JLabel selectedLabel;
	private final JComboBox<String> scaleComboBox;

	private final Map<String, JButton> alphabeticalButtonMap =
			new HashMap<>();

	private static final Float[] ALLOWED_SCALES = new Float[]{
			null,
			2.0f, 2.25f, 2.5f, 2.75f,
			3.0f, 3.25f, 3.5f, 3.75f,
			4.0f, 4.25f, 4.5f, 4.75f,
			5.0f, 5.25f, 5.5f,
			6.0f, 6.5f, 6.75f,
			7.75f, 8.0f
	};

	private MapElementCategories currentEntry;

	@Inject
	public MapIconViewer(
			MapElementManager mapElementManager,
			MapElementType mapElementType,
			HDMinimapConfig config
	) {
		this.mapElementManager = mapElementManager;
		this.mapElementType = mapElementType;
		this.config = config;

		setLayout(new BorderLayout(5, 5));
		add(createHeader(), BorderLayout.NORTH);

		buttonPanel = new JPanel(new BorderLayout());

		JScrollPane scrollPane = new JScrollPane(
				buttonPanel,
				JScrollPane.VERTICAL_SCROLLBAR_ALWAYS,
				JScrollPane.HORIZONTAL_SCROLLBAR_NEVER
		);

		buttonsFlowPanel = new JPanel();

		if (config.mapElementView() == HDMinimapConfig.MapElementView.GRID) {
			buttonsFlowPanel.setLayout(
					new FlowLayout(
							FlowLayout.LEFT,
							6,
							6
					)
			);
		} else {
			buttonsFlowPanel.setLayout(
					new BoxLayout(
							buttonsFlowPanel,
							BoxLayout.Y_AXIS
					)
			);
		}

		for (MapElementCategories element : MapElementCategories.values()) {
			if (element.getType() != mapElementType) {
				continue;
			}

			BufferedImage original =
					mapElementManager.getImage(
							mapElementType,
							element.getMapID()
					);

			if (original == null) {
				continue;
			}

			JButton button;

			if (config.mapElementView() == HDMinimapConfig.MapElementView.LIST) {
				button = createListButton(
						element,
						original
				);
			} else {
				button = createButton(
						element,
						original
				);
			}

			buttonsFlowPanel.add(button);

			alphabeticalButtonMap.put(
					element.getDefaultName(),
					button
			);
		}

		inlineConfigPanel = new JPanel(new BorderLayout());

		inlineConfigPanel.setBackground(
				ColorScheme.DARKER_GRAY_COLOR
		);

		inlineConfigPanel.setBorder(
				BorderFactory.createLineBorder(
						Color.DARK_GRAY
				)
		);

		inlineConfigPanel.setVisible(false);

		selectedLabel = new JLabel(
				"Selected: None"
		);

		selectedLabel.setForeground(
				Color.WHITE
		);

		selectedLabel.setHorizontalAlignment(
				SwingConstants.CENTER
		);

		selectedLabel.setBorder(
				BorderFactory.createEmptyBorder(
						8,
						0,
						8,
						0
				)
		);

		JPanel scalePanel = new JPanel(
				new FlowLayout(
						FlowLayout.LEFT,
						6,
						0
				)
		);

		scalePanel.setBackground(
				ColorScheme.DARKER_GRAY_COLOR
		);

		scalePanel.setBorder(
				BorderFactory.createEmptyBorder(
						0,
						0,
						8,
						0
				)
		);

		scalePanel.add(
				new JLabel("Scale:")
		);

		scaleComboBox = new JComboBox<>();

		for (Float f : ALLOWED_SCALES) {
			scaleComboBox.addItem(
					f == null
							? "Any"
							: f.toString()
			);
		}

		scaleComboBox.addActionListener(e -> {
			if (currentEntry != null) {
				String selected =
						(String) scaleComboBox
								.getSelectedItem();

				Float scale =
						"Any".equals(selected)
								? null
								: Float.parseFloat(selected);

				mapElementManager.setScale(
						currentEntry.getDefaultName(),
						scale
				);

				mapElementManager.updateIcon(
						currentEntry.getDefaultName()
				);
			}
		});

		scalePanel.add(
				scaleComboBox
		);

		inlineConfigPanel.add(
				selectedLabel,
				BorderLayout.NORTH
		);

		inlineConfigPanel.add(
				scalePanel,
				BorderLayout.SOUTH
		);

		buttonPanel.add(
				buttonsFlowPanel,
				BorderLayout.CENTER
		);

		buttonPanel.setPreferredSize(
				new Dimension(
						200,
						1060
				)
		);

		add(
				scrollPane,
				BorderLayout.CENTER
		);

		add(
				inlineConfigPanel,
				BorderLayout.SOUTH
		);
	}

	private JPanel createHeader() {
		JPanel headerPanel = new JPanel(
				new BorderLayout(
						5,
						5
				)
		);

		headerPanel.setBackground(
				ColorScheme.DARK_GRAY_COLOR
		);

		headerPanel.setBorder(
				BorderFactory.createEmptyBorder(
						10,
						5,
						5,
						5
				)
		);

		JPanel toolbar = new JPanel();

		toolbar.setLayout(
				new BoxLayout(
						toolbar,
						BoxLayout.X_AXIS
				)
		);

		toolbar.setBackground(
				ColorScheme.DARK_GRAY_COLOR
		);

		int elementHeight = 28;

		IconTextField searchBar =
				new IconTextField();

		searchBar.setIcon(
				IconTextField.Icon.SEARCH
		);

		searchBar.setPreferredSize(
				new Dimension(
						300,
						elementHeight
				)
		);

		searchBar.setMaximumSize(
				new Dimension(
						Integer.MAX_VALUE,
						elementHeight
				)
		);

		searchBar.setBackground(
				ColorScheme.DARKER_GRAY_COLOR
		);

		searchBar.setHoverBackgroundColor(
				ColorScheme.DARK_GRAY_HOVER_COLOR
		);

		toolbar.add(
				searchBar
		);

		toolbar.add(
				Box.createRigidArea(
						new Dimension(
								5,
								0
						)
				)
		);

		JComboBox<String> sortDropdown =
				getStringJComboBox(
						elementHeight
				);

		if (
				SHOW_SORT_DROPDOWN
						&& mapElementType != MapElementType.MAP_SCENERY
		) {
			toolbar.add(
					sortDropdown
			);
		}

		searchBar.getDocument()
				.addDocumentListener(
						new DocumentListener() {
							private void update() {
								filterAndSortButtons(
										searchBar.getText(),
										(String) sortDropdown
												.getSelectedItem()
								);
							}

							@Override
							public void insertUpdate(
									DocumentEvent e
							) {
								update();
							}

							@Override
							public void removeUpdate(
									DocumentEvent e
							) {
								update();
							}

							@Override
							public void changedUpdate(
									DocumentEvent e
							) {
								update();
							}
						}
				);

		searchBar.addClearListener(
				() -> filterAndSortButtons(
						"",
						(String) sortDropdown
								.getSelectedItem()
				)
		);

		sortDropdown.addActionListener(
				e -> filterAndSortButtons(
						searchBar.getText(),
						(String) sortDropdown
								.getSelectedItem()
				)
		);

		headerPanel.add(
				toolbar,
				BorderLayout.NORTH
		);

		if (
				mapElementType
						!= MapElementType.MAP_SCENERY
		) {
			PluginErrorPanel errorPanel =
					new PluginErrorPanel();

			errorPanel.setBorder(
					new EmptyBorder(
							5,
							5,
							5,
							5
					)
			);

			errorPanel.setContent(
					"Info",
					"Left-click something to toggle it's visibility. "
							+ "If red (hidden), it can also be right-clicked "
							+ "to adjust the minimap zoom scale at which it "
							+ "becomes hidden (default is any zoom level)."
			);

			headerPanel.add(
					errorPanel,
					BorderLayout.SOUTH
			);
		}

		return headerPanel;
	}

	private static JComboBox<String> getStringJComboBox(
			int elementHeight
	) {
		String[] sortOptions = new String[]{
				"Alphabetical",
				"Grouping"
		};

		JComboBox<String> sortDropdown =
				new JComboBox<>(
						sortOptions
				);

		FontMetrics fm =
				sortDropdown.getFontMetrics(
						sortDropdown.getFont()
				);

		int maxWidth = 0;

		for (String item : sortOptions) {
			int width =
					fm.stringWidth(item);

			if (width > maxWidth) {
				maxWidth = width;
			}
		}

		maxWidth += 40;

		sortDropdown.setPreferredSize(
				new Dimension(
						maxWidth,
						elementHeight
				)
		);

		sortDropdown.setMaximumSize(
				new Dimension(
						maxWidth,
						elementHeight
				)
		);

		return sortDropdown;
	}

	private void filterAndSortButtons(
			String query,
			String sortOption
	) {
		query = query
				.trim()
				.toLowerCase(
						Locale.ROOT
				);

		boolean grouping =
				"Grouping".equals(
						sortOption
				);

		List<String> categories =
				new ArrayList<>(
						mapElementManager
								.getAlphabeticalCategories(
										mapElementType,
										grouping
								)
				);

		buttonsFlowPanel.removeAll();

		for (String category : categories) {
			if (category == null) {
				continue;
			}

			if (
					!category
							.toLowerCase(
									Locale.ROOT
							)
							.contains(query)
			) {
				continue;
			}

			JButton button =
					alphabeticalButtonMap
							.get(category);

			if (button != null) {
				buttonsFlowPanel.add(
						button
				);
			}
		}

		buttonsFlowPanel.revalidate();
		buttonsFlowPanel.repaint();

		buttonPanel.revalidate();
		buttonPanel.repaint();
	}

	private JButton createButton(
			MapElementCategories entry,
			BufferedImage image
	) {
		JButton button = new JButton();

		button.setPreferredSize(
				new Dimension(
						BUTTON_SIZE,
						BUTTON_SIZE
				)
		);

		button.setBorder(
				BorderFactory.createLineBorder(
						Color.GRAY
				)
		);

		button.setFocusPainted(false);
		button.setOpaque(true);

		button.setIcon(
				new ImageIcon(image)
		);

		button.setToolTipText(
				entry.getDefaultName()
		);

		setButtonState(
				button,
				entry
		);

		button.addActionListener(
				e -> toggleEntry(
						button,
						entry
				)
		);

		button.addMouseListener(
				createRightClickListener(
						button,
						entry
				)
		);

		return button;
	}

