		);

		button.addMouseListener(
				createRightClickListener(
						button,
						entry
				)
		);

		return button;
	}

	private void setButtonState(
			JButton button,
			MapElementCategories entry
	) {
		boolean isDisabled =
				mapElementManager
						.getSetting(
								entry.getDefaultName()
						)
						.isDisabled();

		button.setBackground(
				isDisabled
						? new Color(
						255,
						0,
						0,
						120
				)
						: ColorScheme.DARKER_GRAY_COLOR
		);
	}

	private void toggleEntry(
			JButton button,
			MapElementCategories entry
	) {
		boolean active =
				!isActive(button);

		button.setBackground(
				active
						? new Color(
						255,
						0,
						0,
						120
				)
						: ColorScheme.DARKER_GRAY_COLOR
		);

		boolean newState =
				!mapElementManager
						.getSetting(
								entry.getDefaultName()
						)
						.isDisabled();

		mapElementManager.setDisabled(
				entry.getDefaultName(),
				newState
		);

		hideInlineConfig();

		mapElementManager.updateIcon(
				entry.getDefaultName()
		);
	}

	private MouseAdapter createRightClickListener(
			JButton button,
			MapElementCategories entry
	) {
		return new MouseAdapter() {
			@Override
			public void mousePressed(
					MouseEvent e
			) {
				if (
						SwingUtilities
								.isRightMouseButton(e)
								&& isActive(button)
				) {
					showInlineConfig(entry);
				}
			}
		};
	}

	private boolean isActive(
			JButton button
	) {
		return button
				.getBackground()
				.equals(
						new Color(
								255,
								0,
								0,
								120
						)
				);
	}

	private void showInlineConfig(
			MapElementCategories entry
	) {
		if (
				mapElementType
						== MapElementType.MAP_SCENERY
		) {
			return;
		}

		currentEntry = entry;

		selectedLabel.setText(
				entry.getDefaultName()
						+ ": "
		);

		Float currentScale =
				mapElementManager
						.getSetting(
								entry.getDefaultName()
						)
						.getScale();

		if (currentScale == null) {
			scaleComboBox.setSelectedIndex(
					0
			);
		} else {
			for (
					int i = 0;
					i < ALLOWED_SCALES.length;
					i++
			) {
				if (
						ALLOWED_SCALES[i] != null
								&& ALLOWED_SCALES[i]
								.equals(currentScale)
				) {
					scaleComboBox
							.setSelectedIndex(i);

					break;
				}
			}
		}

		inlineConfigPanel.setVisible(
				true
		);

		revalidate();
		repaint();
	}

	private void hideInlineConfig() {
		currentEntry = null;

		selectedLabel.setText(
				"Selected: None"
		);

		inlineConfigPanel.setVisible(
				false
		);

		revalidate();
		repaint();
	}
}

